loginUrl:
Url();

function getUrl() {
    try {
        let urls = Array.from(org.jsoup.Jsoup.parse(java.get("https://www.manwaku.cc/", {}).body()).select('.cards a'), x => x.attr('href'));
        if (urls.length === 0) throw new Error('未获取到站源');
        let data = JSON.parse(source.getVariable());
        data.Urls = urls;
        source.setVariable(JSON.stringify(data, null, "\t"));
        java.toast(`获取到${urls.length}个站源\n${urls.join('\n')}`);
    } catch (e) {
        java.log(e.message)
        java.toast('获取失败，请检查网络');
    }
}

function setUrl(n) {
    let data = JSON.parse(source.getVariable());
    if (n + 1 > data.Urls.length) return java.toast(`暂时没有站源${n + 1}`);
    data.sourceurl = data.Urls[n];
    source.setVariable(JSON.stringify(data, null, "\t"));
    java.toast(`当前站源已切换到：\n${data.Urls[n]}`);
}

function login() {}

function Login() {
    let username = String(result?.["用户名（3-50个字符）"] ?? '') || "axb";
    let password = String(result?.["密码（6-20个字符）"] ?? '') || "123456789@";
    let url = `${Url()}/api/user/login`;
    try {
        let response = JSON.parse(java.post(url, JSON.stringify({
            username,
            password
        }), {
            "x-requested-with": "XMLHttpRequest",
            "Content-Type": "application/json"
        }).body());
        if (!/successful/.test(response.msg)) return java.toast(response.msg);
        let token = response.data.token;
        source.putLoginHeader(JSON.stringify({
            "Authorization": "Bearer " + token,
            "Cookie": "authToken=" + token
        }));
        java.toast(`\n用户：${username}\n登录成功！`);
    } catch (e) {
        java.log(e.message);
        java.toast('请求失败，请检查网络状况！');
    }
}

function LoginOut() {
    source.removeLoginHeader();
    cookie.removeCookie(Url());
    java.toast('登出成功！');
}

function register() {
    let username = result?.["用户名（3-50个字符）"] ?? '';
    let password = result?.["密码（6-20个字符）"] ?? '';
    let email = result?.["邮箱（注册填入）"] ?? '';
    if (!String(username) || !String(password) || !String(email)) return java.toast('请填入必要数据');
    if (String(username).length < 3 || String(username).length > 50) return java.toast('用户名不符合要求');
    if (String(password).length < 6 || String(password).length > 20) return java.toast('密码不符合要求');
    try {
        let url = `${Url()}/api/user/register`;
        let body = JSON.stringify({
            username,
            password,
            email,
            "nickname": username
        });
        let response = JSON.parse(java.post(url, body, {
            "x-requested-with": "XMLHttpRequest",
            "Content-Type": "application/json"
        }).body());
        if (!/successful/.test(response.msg)) return java.toast(response.msg);
        java.log(`\n用户名：${username}\n注册邮箱：${email}\n密码：${password}`);
        let token = response.data.token;
        source.putLoginInfo(JSON.stringify(result));
        source.putLoginHeader(JSON.stringify({
            "Authorization": "Bearer " + token,
            "Cookie": "authToken=" + token
        }));
        java.toast(`\n用户：${username}\n注册并登录成功！\n用户数据已打印至源日志`);
    } catch (e) {
        java.log(e.message);
        java.toast('请求失败，请检查网络状况！');
    }
}

